function makeSpaces(spec, kind, collective, index) {
  const lodging = kind === 'habitat' || kind === 'hospitality' && index < 20;
  const upper = lodging || kind === 'education';
  const rooms = [{name:lodging?'Vestibule des affaires de séjour':'Accueil et préparation des dossiers',kind:'desk',resource:'scrap'}, ...spec.rooms];
  if (lodging) rooms.push(
    {name:collective?'Salle de repas résidentiels':'Cuisine des occupants',kind:'fridge',resource:'food'},
    {name:collective?'Couchage des résidents':'Chambre du foyer',kind:'bed',resource:'wood'},
    {name:collective?'Rangement du linge de séjour':'Armoire des affaires privées',kind:'wardrobe',resource:'wood'}
  );
  else if(kind === 'health') rooms.push(
    {name:'Réserve des accessoires de service',kind:'crate',resource:spec.rooms.some(r=>r.resource==='medicine')?'medicine':'scrap'},
    {name:'Local de lavage hors service',kind:'sink',resource:'scrap'},
    {name:'Rangement des affaires de personnel',kind:'wardrobe',resource:'wood'}
  );
  else if(kind === 'education') rooms.push(
    {name:'Salle des supports pédagogiques',kind:'table',resource:'wood'},
    {name:'Réserve d\'accessoires de cours',kind:'crate',resource:'scrap'},
    {name:'Rangement des affaires de formation',kind:'wardrobe',resource:'wood'}
  );
  else rooms.push(
    {name:'Réserve de livraison alimentaire',kind:'crate',resource:'food'},
    {name:'Local de lavage du service',kind:'sink',resource:'scrap'},
    {name:'Salle de repas des visiteurs',kind:'table',resource:'wood'}
  );
  return rooms.map((r, i) => ({id:'espace-'+String(i+1).padStart(2,'0'),name:r.name,z:upper && i>=5?1:0,
    usage:r.name+' : '+furnitureRole[r.kind], resource:r.resource,
    props:[{kind:r.kind,resource:r.resource}]}));
}
function make(spec, kind, index, id) {
  const collective = kind==='habitat' && index>=40 || kind==='hospitality' && index<20;
  const family = kind==='habitat' ? collective?'Habitat collectif':'Habitat individuel'
    :kind==='health'?index<40?'Santé':'Administration et communauté'
    :kind==='hospitality'?index<20?'Hôtellerie et hébergement':'Alimentation et restauration'
    :'Éducation et connaissance';
  const spaces=makeSpaces(spec,kind,collective,index);
  const levels=[...new Set(spaces.map(s=>s.z))].sort((a,b)=>a-b);
  const layout=layouts[kind][index%4];
  const roofFamily=kind==='habitat'?collective?'collective':'cottage':kind==='health'?index<40?'clinic':'civic':kind==='hospitality'?index<20?'hotel':'retail':'school';
  // Compact domestic programmes and larger public programmes reserve room and
  // hallway dimensions first; no minimal envelope contains maximal furniture.
  const width=kind==='habitat'?collective?38:32:kind==='education'?42:kind==='health'?36:40;
  const height=levels.length>1?36:40;
  const first=spec.rooms[0].name, last=spec.rooms.at(-1).name;
  const resources=[...new Set(spaces.map(s=>s.resource))];
  const urban=kind!=='habitat'||collective;
  return {
    id:'DW-'+id,name:spec.name,family,
    purpose:spec.purpose+'. Le lieu abandonné est un programme d\'exploration et de récupération ; son ancien métier ou service ne devient pas une activité simulée.',
    architecture:{width,height,levels,layout,roofFamily,material:material[kind]},spaces,
    access:{
      public:'Entrée avant depuis le raccord routier, puis '+(layout==='offset'?'couloir décentré':layout==='cross'?'axe central et dégagement transversal':layout==='gallery'?'galerie centrale élargie':'couloir médian')+' vers '+first.toLowerCase()+'. Chaque pièce ouvre sur ce passage ; aucune traversée de meuble n\'est requise.',
      service:'Accès arrière par l\'ouverture de retour ; rejoindre '+last.toLowerCase()+' et les réserves depuis la circulation, sans emprunter les espaces privés comme raccourci.',
      return:'Retour par l\'axe intérieur jusqu\'à l\'ouverture avant ou arrière ; '+(levels.length>1?'le palier et l\'escalier existants relient le niveau 1 au rez-de-chaussée avant la sortie.':'toutes les pièces restent au même niveau sans passage souterrain implicite.'),
      width_m:layout==='gallery'?3.2:layout==='offset'?2.2:2.6
    },
    placement:{mode:urban?'town':'any',biomes:urban?['meadow','bocage','brownfield','orchard']:['meadow','bocage','mixed','deciduous','orchard'],townKinds:urban?['village','bourg','ville','grande-ville']:['hameau','village','bourg']},
    supplies:'Les reliquats de '+resources.join(', ')+' appartiennent aux contenants identifiés de '+first.toLowerCase()+' et des autres pièces. Chaque contenant reçoit une quantité finie dans les bornes natives 3–12 ; l\'ajout d\'une forme de toiture ne double pas ce budget. Prélever, sortir, changer d\'étage puis recharger conserve les quantités restantes, sans livraison ni production.',
    risks:[
      first+' ouvre sur un passage public : reconnaître les contacts régionaux avant de s\'arrêter pour fouiller.',
      (levels.length>1?'La visite du niveau résidentiel ou pédagogique impose un aller-retour par le même escalier ;':'La visite du fond du bâtiment allonge le retour vers la route ;')+' un sac chargé et '+last.toLowerCase()+' peuvent prolonger l\'exposition.',
      'Les traces de l\'ancien usage expliquent l\'abandon ; elles ne déclenchent ni maladie, réaction chimique, incendie ou service autonome.'
    ],
    night:'Les appareils et luminaires anciens de '+spec.name.toLowerCase()+' sont éteints. Une lampe réellement portée ou posée garde son coût et son niveau ; vérifier '+first.toLowerCase()+', les portes et le retour, sans halo traversant les murs ou '+(levels.length>1?'le plancher.':'une réserve fermée.'),
    variants:[
      'Forme compacte : '+roofFamily+' avec couverture basse réparée ; conserver '+width+' × '+height+' m, '+levels.length+' niveau'+(levels.length>1?'x':'')+' et le circuit '+layout+' de '+first.toLowerCase()+' à '+last.toLowerCase()+'.',
      'Forme de service : autre profil natif de toiture et matière de couverture, avec reprise de zinc ou de béton visible ; maintenir les mêmes salles, accès, solides et réserves de '+spec.name.toLowerCase()+'. Cette forme ne constitue pas une fiche supplémentaire.'
    ],
    interactions:[
      'Entrer par le raccord physique, reconnaître '+first.toLowerCase()+' puis fouiller les contenants des espaces utiles en gardant le passage de retour libre.',
      'Comparer les reliquats de '+resources.join(', ')+' et la place du sac, transporter physiquement la récupération au dépôt pour la reconstruction ou les usages existants.',
      'Revenir vers '+last.toLowerCase()+' après sauvegarde pour terminer une réserve partiellement prise ; aucun métier, soin ou achat n\'est lancé par la consultation de la fiche.'
    ],
    qa:[
      'Vérifier la réservation de '+width+' × '+height+' m hors route et voisins avant d\'accepter la parcelle.',
      'Parcourir entrée → '+first+' → '+last+' → sortie avec le rayon réel du joueur et les portes dégagées.',
      'Atteindre les '+spaces.length+' espaces fonctionnels depuis leur circulation sans traverser un meuble.',
      levels.length>1?'Monter au niveau 1, visiter les trois pièces puis reprendre le palier et redescendre sans téléportation.':'Parcourir tout le rez-de-chaussée sans sous-sol ni issue inventée.',
      'Vérifier chaque mobilier natif et son identité stable par lieu, étage et contenant.',
      'Prélever une partie du stock, sauvegarder et reprendre ; aucun contenant fouillé ne doit se remplir.',
      'Comparer les deux profils de couverture sans modifier collisions, étages ou budget de récupération.',
      'Contrôler de nuit l\'entrée et le retour avec une source réellement portée, éteinte ensuite sans lumière gratuite.'
    ],
    story:'Dans '+first.toLowerCase()+', des emplacements de dossiers et d\'objets évoquent l\'ancienne fonction : '+spec.purpose.toLowerCase()+'. Le rangement de '+last.toLowerCase()+' et les affaires laissées au fond racontent une interruption du lieu sans présumer de survivants, de clients ou d\'une activité encore présente.'
  };
}
(async()=>{
  let next=3001;
  const fiches=[];
  for(const group of groups){
    if(group.rows.length!==group.count)throw Error(group.kind+' : '+group.rows.length+' lignes, attendu '+group.count);
    group.rows.forEach((s,i)=>fiches.push(make(s,group.kind,i,next++)));
  }
  const lot={schemaVersion:1,version:'1.58.0',count:250,fiches};
  const {validateLot}=await import(pathToFileURL(path.join(root,'codex-3000/addendum-1.58/validation.mjs')));
  validateLot(lot,'A');
  const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLowerCase();
  const old=new Set(JSON.parse(fs.readFileSync(path.join(root,'codex-3000/INDEX_3000.json'),'utf8')).entries.map(x=>norm(x.name)));
  for(const f of fiches)if(old.has(norm(f.name)))throw Error('Nom historique répété : '+f.name);
  fs.writeFileSync(out,JSON.stringify(lot,null,2)+'\n');
  console.log(JSON.stringify({file:path.relative(root,out),count:fiches.length,first:fiches[0].id,last:fiches.at(-1).id,families:[...new Set(fiches.map(x=>x.family))],spaces:fiches.reduce((n,p)=>n+p.spaces.length,0)}));
})().catch(error=>{console.error(error.message);process.exitCode=1;});
